// Chasing marquee light bulbs
(function () {
  var box = document.getElementById("bulbs");
  var bulbs = [];
  function build() {
    box.innerHTML = "";
    bulbs = [];
    var w = box.clientWidth, h = box.clientHeight, gap = 34;
    var nx = Math.max(2, Math.round(w / gap)), ny = Math.max(2, Math.round(h / gap));
    var pts = [], i;
    for (i = 0; i < nx; i++) pts.push([(i / nx) * w, 0]);
    for (i = 0; i < ny; i++) pts.push([w, (i / ny) * h]);
    for (i = 0; i < nx; i++) pts.push([w - (i / nx) * w, h]);
    for (i = 0; i < ny; i++) pts.push([0, h - (i / ny) * h]);
    pts.forEach(function (p) {
      var b = document.createElement("span");
      b.className = "bulb";
      b.style.left = p[0] + "px";
      b.style.top = p[1] + "px";
      box.appendChild(b);
      bulbs.push(b);
    });
  }
  var tick = 0;
  setInterval(function () {
    tick++;
    bulbs.forEach(function (b, i) { b.classList.toggle("on", (i + tick) % 3 === 0); });
  }, 180);
  build();
  window.addEventListener("resize", build);
})();

// Applause sound — click the Applause sign to switch the sound on
(function () {
  var sign = document.getElementById("applause");
  var doors = Array.prototype.slice.call(document.querySelectorAll(".door"));
  var btn = document.getElementById("pick");
  var clap = new Audio("data:audio/mpeg;base64,");
  clap.preload = "auto";
  var soundOn = false;

  function playClap() {
    try { clap.currentTime = 0; } catch (e) {}
    var p = clap.play();
    if (p && p.catch) p.catch(function () {});
  }

  function applaud(times, withSound) {
    var n = 0;
    if (withSound && soundOn) playClap();
    var t = setInterval(function () {
      sign.classList.toggle("lit");
      if (++n >= times * 2) { clearInterval(t); sign.classList.remove("lit"); }
    }, 250);
  }

  sign.addEventListener("click", function () {
    soundOn = true;
    playClap();
  });

  btn.addEventListener("click", function () {
    btn.disabled = true;
    doors.forEach(function (d) { d.classList.remove("chosen"); });
    var steps = 12 + Math.floor(Math.random() * doors.length), i = 0, last;
    var t = setInterval(function () {
      if (last) last.classList.remove("chosen");
      last = doors[i % doors.length];
      last.classList.add("chosen");
      if (++i >= steps) {
        clearInterval(t);
        last.scrollIntoView({ behavior: "smooth", block: "center" });
        applaud(4, true);
        btn.disabled = false;
      }
    }, 110);
  });

  doors.forEach(function (d) { d.addEventListener("mouseenter", function () { applaud(1, false); }); });
  setInterval(function () { applaud(2, false); }, 9000);
})();
